import java.util.Scanner;
public class JBooleanDryHot3 {
	public static void main(String[] args) {
		//Khatwa 1: Qra madkhalat al-mustakhdim
		Scanner scan = new Scanner(System.in);
		System.out.println("Adkhil ma idha kanat al-harara kathira (true or false):");
		boolean tooHot = scan.nextBoolean();	
		System.out.println("Adkhil ma idha kanat al-jafa kathira (true or false):");
		boolean tooDry = scan.nextBoolean();		
		scan.close();
		//Khatwa 2: Uktub ta'bir boolean lita'ayin iza kanat al-harara kathira walakin laysa jaffan
		boolean value = tooHot && !tooDry;
		System.out.println(value);
	}
}
